#!/usr/bin/env node
// =============================================================================
// Build script: bundle the KLITE RPmod ES modules into a single usermod.
//
// Esolite's mod manager imports one classic-script JS file, so esbuild bundles
// src/main.js (which imports and starts every module) into one IIFE:
//   KLITE-RPmod.js  (repo root — the file users load into Esolite)
//
// No minification: the bundle stays readable for users and bug reports.
//
// Usage:  npm run build   (or: node scripts/build-bundle.js)
// Re-run after editing any source file.
// =============================================================================
const fs = require('fs');
const path = require('path');
const esbuild = require('esbuild');

const ROOT = path.join(__dirname, '..');
const OUT = path.join(ROOT, 'KLITE-RPmod.js');

// Credits in the header of the file users share. The SRD attribution is taken verbatim from
// the generated data file (its second line), so it can never drift from SRD.attribution.
const srdAttribution = fs.readFileSync(path.join(ROOT, 'src', 'data', 'srd52.js'), 'utf8')
    .split('\n')[1].replace(/^\/\/ /, '');
if (!srdAttribution.startsWith('This work includes material from the System Reference Document 5.2.1')) {
    throw new Error('build-bundle: SRD attribution not found on line 2 of src/data/srd52.js');
}

const banner = [
    '// ' + '='.repeat(77),
    '// KLITE RPmod - combined usermod bundle',
    '// ' + '='.repeat(77),
    `// Generated by scripts/build-bundle.js (esbuild) — v${require(path.join(ROOT, "package.json")).version}`,
    '// Do not edit this file directly - edit src/ and re-run `npm run build`.',
    '//',
    '// Credits',
    '// ' + srdAttribution,
    '// Zone combat: the idea of zones instead of a grid comes from the zone combat house rules of',
    '// Ultimate Dungeon Terrain (Dungeon Craft); RPmod implements its own rules, nothing is copied.',
    '// Icons: Lucide (ISC license; some icons derived from Feather, MIT license) — licence below.',
    '',
].join('\n');

const result = esbuild.buildSync({
    entryPoints: [path.join(ROOT, 'src', 'main.js')],
    outfile: OUT,
    bundle: true,
    format: 'iife',
    platform: 'browser',
    target: 'es2020',
    charset: 'utf8',
    legalComments: 'inline',
    banner: { js: banner },
    metafile: true,
    logLevel: 'warning',
});

for (const [file, info] of Object.entries(result.metafile.inputs)) {
    console.log(`+ ${path.basename(file).padEnd(28)} ${(info.bytes / 1024).toFixed(0)} KB`);
}
const out = Object.values(result.metafile.outputs)[0];
console.log(`\n= wrote ${path.basename(OUT)}  (${(out.bytes / 1024).toFixed(0)} KB)`);
